tasks.command:
$ErrorActionPreference = 'Stop'
az acr build --registry acrsovereignshield16555 --image sovereignshield-portal:live-20260915-repair --file Dockerfile . --output none
if ($LASTEXITCODE -ne 0) { throw 'ACR build/push failed; no image update was attempted.' }
az acr repository show --name acrsovereignshield16555 --image sovereignshield-portal:live-20260915-repair --query digest -o tsv
if ($LASTEXITCODE -ne 0) { throw 'Image digest verification failed.' }
az containerapp update --name ca-sovereignshield-portal --resource-group rg-sovereignshield --image acrsovereignshield16555.azurecr.io/sovereignshield-portal:live-20260915-repair --max-replicas 1 --output none
if ($LASTEXITCODE -ne 0) { throw 'Verified gateway image update failed.' }

$ErrorActionPreference = 'Stop'
$env:DATABRICKS_HOST = 'https://adb-7405613190562799.19.azuredatabricks.net'
$env:DATABRICKS_AUTH_TYPE = 'azure-cli'
Remove-Item Env:ARM_CLIENT_ID,Env:ARM_CLIENT_SECRET,Env:DATABRICKS_ACCOUNT_ID,Env:BUNDLE_VAR_ingestion_cluster -ErrorAction SilentlyContinue
databricks bundle deploy -t dev
if ($LASTEXITCODE -ne 0) { throw 'App source deployment failed.' }
databricks bundle run sovereignshield_portal -t dev
if ($LASTEXITCODE -ne 0) { throw 'Databricks App update failed.' }
az acr build --registry acrsovereignshield16555 --image sovereignshield-portal:live-20260915-auth --file Dockerfile . --output none
if ($LASTEXITCODE -ne 0) { throw 'Gateway image build failed.' }
az containerapp update --name ca-sovereignshield-portal --resource-group rg-sovereignshield --image acrsovereignshield16555.azurecr.io/sovereignshield-portal:live-20260915-auth --max-replicas 1 --output none
if ($LASTEXITCODE -ne 0) { throw 'Gateway image rollout failed.' }
